INSERT INTO `areaclic` VALUES ('mdPTriceps','Prega cutnea do trceps','ADIPOMETRO',,'{\\rtf1\\ansi\\deff0\\deftab720{\\fonttbl{\\f0\\fswiss MS Sans Serif;}{\\f1\\froman\\fcharset2 Symbol;}{\\f2\\fswiss\\fcharset1 MS Sans Serif;}{\\f3\\fswiss\\fprq2 Arial;}{\\f4\\fswiss\\fcharset1 MS Sans Serif;}}\r\n{\\colortbl\\red0\\green0\\blue0;}\r\n\\deflang1046\\pard\\plain\\f3\\fs22\\b Prega cut\\\'e2nea do tr\\\'edceps\\plain\\f3\\fs22 \r\n\\par \r\n\\par Deve ser medida na parte posterior do antebra\\\'e7o, sobre o m\\\'fasculo triciptal, no ponto m\\\'e9dio entre o acr\\\'f4mio e o ol\\\'e9crano, determinado da mesma maneira descrita para medir a CB. Estando o bra\\\'e7o relaxado, pin\\\'e7a-se a pele e o tecido subcut\\\'e2neo entre o polegar e o indicador e aplica-se o adip\\\'f4metro a 1 cm abaixo dos dedos que pin\\\'e7avam a prega e, sem soltar, faz-se 3 leituras, utilizando a m\\\'e9dia das 2 mais pr\\\'f3ximas, no mil\\\'edmetro mais pr\\\'f3ximo.\r\n\\par \\plain\\f4\\fs16 \r\n\\par }\r\n',7);
